namespace vb {namespace {
std::uint64_t Hash(std::string_view s){std::uint64_t h=1469598103934665603ull;for(unsigned char c:s){h^=c;h*=1099511628211ull;}return h;}
std::uint16_t Candidate(std::uint64_t h,unsigned shift,std::uint16_t base,std::uint16_t span){return static_cast<std::uint16_t>(base+((h>>shift)%span));}
}
void RegionManager::Validate(const RegionConfig&r){if(r.country!="JPN")throw std::runtime_error("Milestone 6 supports country JPN only");if(r.timezone!="Asia/Tokyo")throw std::runtime_error("Japanese channels require Asia/Tokyo");if(std::find(Prefectures().begin(),Prefectures().end(),r.prefecture)==Prefectures().end())throw std::runtime_error("unknown Japanese prefecture");}
const std::vector<std::string>&RegionManager::Prefectures(){static const std::vector<std::string>p={"北海道","青森県","岩手県","宮城県","秋田県","山形県","福島県","茨城県","栃木県","群馬県","埼玉県","千葉県","東京都","神奈川県","新潟県","富山県","石川県","福井県","山梨県","長野県","岐阜県","静岡県","愛知県","三重県","滋賀県","京都府","大阪府","兵庫県","奈良県","和歌山県","鳥取県","島根県","岡山県","広島県","山口県","徳島県","香川県","愛媛県","高知県","福岡県","佐賀県","長崎県","熊本県","大分県","宮崎県","鹿児島県","沖縄県"};return p;}
ChannelIds IdManager::Generate(std::string_view name,std::span<const ExistingIds>existing){auto h=Hash(name);for(unsigned attempt=0;attempt<65535;++attempt){ChannelIds ids;ids.original_network_id=Candidate(h+attempt,0,0x7000,0x0ffe);ids.network_id=ids.original_network_id;ids.transport_stream_id=Candidate(h+attempt,16,0x7000,0x0ffe);ids.service_id=Candidate(h+attempt,32,1,0xfffe);ids.download_data_id=Candidate(h+attempt,8,0x8000,0x7ffe);ids.logo_id=Candidate(h+attempt,48,1,0x1fe);const bool collision=std::any_of(existing.begin(),existing.end(),[&](const auto&e){return(e.original_network_id==ids.original_network_id&&e.transport_stream_id==ids.transport_stream_id)||(e.original_network_id==ids.original_network_id&&e.service_id==ids.service_id)||e.download_data_id==ids.download_data_id;});if(!collision)return ids;}throw std::runtime_error("Auto ID candidate space exhausted");}
void IdManager::Validate(std::span<const VirtualChannel>c,std::span<const ExistingIds>existing){std::set<std::pair<std::uint16_t,std::uint16_t>>ts,services;std::set<std::uint16_t>downloads;std::set<std::uint16_t>ports;for(const auto&x:c){RegionManager::Validate(x.region);if(x.remote_control_key_id<1||x.remote_control_key_id>12)throw std::runtime_error("remote_control_key_id must be 1..12");if(!ports.insert(x.udp_port).second)throw std::runtime_error("duplicate UDP port");if(!ts.emplace(x.ids.original_network_id,x.ids.transport_stream_id).second)throw std::runtime_error("duplicate ONID+TSID");if(!services.emplace(x.ids.transport_stream_id,x.ids.service_id).second)throw std::runtime_error("duplicate TSID+SID");if(x.si.logo.enabled&&!downloads.insert(x.ids.download_data_id).second)throw std::runtime_error("duplicate download_data_id");for(const auto&e:existing)if((e.original_network_id==x.ids.original_network_id&&e.transport_stream_id==x.ids.transport_stream_id)||(e.original_network_id==x.ids.original_network_id&&e.service_id==x.ids.service_id)||(x.si.logo.enabled&&e.download_data_id==x.ids.download_data_id))throw std::runtime_error("channel IDs collide with imported existing IDs");}}
std::vector<ExistingIds>IdManager::LoadExistingJson(const std::filesystem::path&p){std::ifstream f(p);if(!f)throw std::runtime_error("existing ID file cannot be opened");const std::string s((std::istreambuf_iterator<char>(f)),{});std::regex object(R"json(\{[^}]*\})json"),field(R"json("(original_network_id|transport_stream_id|service_id|download_data_id)"\s*:\s*(\d+))json");std::vector<ExistingIds>out;for(auto i=std::sregex_iterator(s.begin(),s.end(),object);i!=std::sregex_iterator();++i){ExistingIds x;const auto item=i->str();for(auto j=std::sregex_iterator(item.begin(),item.end(),field);j!=std::sregex_iterator();++j){const auto v=std::stoul((*j)[2]);if(v>65535)throw std::runtime_error("existing ID exceeds uint16");const auto k=(*j)[1].str();if(k=="original_network_id")x.original_network_id=static_cast<std::uint16_t>(v);else if(k=="transport_stream_id")x.transport_stream_id=static_cast<std::uint16_t>(v);else if(k=="service_id")x.service_id=static_cast<std::uint16_t>(v);else x.download_data_id=static_cast<std::uint16_t>(v);}out.push_back(x);}return out;}
ChannelManager::ChannelManager(std::vector<VirtualChannel>c,std::vector<ExistingIds>e):channels_(std::move(c)){std::sort(channels_.begin(),channels_.end(),[](auto&a,auto&b){return a.channel_index<b.channel_index;});IdManager::Validate(channels_,e);}
const VirtualChannel*ChannelManager::GetChannel(std::uint32_t space,std::uint32_t channel)const{if(space)return nullptr;const auto i=std::find_if(channels_.begin(),channels_.end(),[&](const auto&c){return c.channel_index==channel;});return i==channels_.end()?nullptr:&*i;}
}
